package tss

import (
	"os"
	"path/filepath"
	"testing"
)

// Cross-version fixtures generated by the v4.1.0 tree (tag v4.1.0,
// 92362c6b) with its own AesEncrypt/EciesEncrypt/DeriveLANSessionKey.
// Test-only keys. See testdata/xversion (regeneration notes in the
// Wave 6 Phase 0 report).

func xversionFixture(t *testing.T, name string) string {
	t.Helper()
	b, err := os.ReadFile(filepath.Join("..", "testdata", "xversion", name))
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

func TestXVersion_TrioChunkFromV410(t *testing.T) {
	derivedKey, err := DeriveLANSessionKey("xv-session-1", "192.168.1.20")
	if err != nil {
		t.Fatal(err)
	}
	got, err := DecryptLANRelayPayload(xversionFixture(t, "lan-trio-chunk.txt"), derivedKey)
	if err != nil {
		t.Fatalf("decrypt v4.1.0 trio chunk: %v", err)
	}
	if want := xversionFixture(t, "payload.txt"); got != want {
		t.Fatalf("payload mismatch: got %q want %q", got, want)
	}
}

func TestXVersion_TagFromV410(t *testing.T) {
	derivedKey, err := DeriveLANSessionKey("xv-session-1", "192.168.1.20")
	if err != nil {
		t.Fatal(err)
	}
	tag, err := computePayloadAuthTag(xversionFixture(t, "payload.txt"), derivedKey)
	if err != nil {
		t.Fatal(err)
	}
	if want := xversionFixture(t, "lan-trio-tag.txt"); tag != want {
		t.Fatalf("tag mismatch: got %q want %q", tag, want)
	}
}

func TestXVersion_EciesChunkFromV410(t *testing.T) {
	// Exercises F41's ecies v2.0.8 against a ciphertext produced by
	// v4.1.0's ecies/go v2.0.3 (wire-format compatibility).
	priv := xversionFixture(t, "ecies-priv.txt")
	got, err := EciesDecrypt(xversionFixture(t, "ecies-chunk.txt"), priv)
	if err != nil {
		t.Fatalf("decrypt v4.1.0 ecies chunk: %v", err)
	}
	if want := xversionFixture(t, "payload.txt"); got != want {
		t.Fatalf("payload mismatch: got %q want %q", got, want)
	}
}

func TestXVersion_LegacyBackupFromV410(t *testing.T) {
	// Real v4.1.0-era backup blob (CBC + SHA-256(password) key, produced
	// by the v4.1.0 tree) must import through the legacy path.
	res, err := BackupDecrypt(xversionFixture(t, "legacy-backup.txt"), "CrossVersion!234")
	if err != nil {
		t.Fatalf("legacy backup decrypt: %v", err)
	}
	if !res.Legacy {
		t.Fatal("v4.1.0 backup must take the legacy path (Legacy=true)")
	}
	want := xversionFixture(t, "dkls-share-0.json")
	if res.Plaintext != want {
		t.Fatalf("backup plaintext mismatch (len got %d want %d)", len(res.Plaintext), len(want))
	}
}
